import "./Week.css";

const Week = () => {
  const data = {
    dt: 1736769600,
    main: {
      temp: 272.24,
      feels_like: 272.24,
      temp_min: 272.24,
      temp_max: 277.55,
      pressure: 1028,
      sea_level: 1028,
      grnd_level: 901,
      humidity: 64,
      temp_kf: -5.31,
    },
    weather: [
      { id: 803, main: "Clouds", description: "broken clouds", icon: "04d" },
    ],
    clouds: { all: 75 },
    wind: { speed: 0.17, deg: 295, gust: 0.61 },
    visibility: 10000,
    pop: 0,
    sys: { pod: "d" },
    dt_txt: "2025-01-13 12:00:00",
  };

  const dtTxt = data.dt_txt;
  const day = dtTxt.split(" ")[0].split("-")[2];

  return (
    <div>
      <p>{day}</p>
    </div>
  );
};

export default Week;
